[
  {
    "vulnerability": "SQL injection",
    "function": "do_login",
    "severity": "HIGH",
    "reason": "User-supplied 'user' and 'pw' values are interpolated directly into a SQL query via f-string, allowing an attacker to bypass authentication or extract arbitrary data (e.g., ' OR '1'='1)."
  },
  {
    "vulnerability": "Reflected Cross-Site Scripting (XSS)",
    "function": "do_reflect",
    "severity": "HIGH",
    "reason": "The 'name' query-parameter value is inserted into an HTML response without any encoding or sanitisation, allowing arbitrary script execution in the victim's browser."
  },
  {
    "vulnerability": "OS Command Injection",
    "function": "do_ping",
    "severity": "HIGH",
    "reason": "The 'host' parameter is concatenated into a shell command string without sanitisation, so shell metacharacters (e.g., '; rm -rf /') would be executed if the command were actually run via os.system or subprocess."
  },
  {
    "vulnerability": "Information Disclosure (error/query leakage)",
    "function": "do_login",
    "severity": "MEDIUM",
    "reason": "On a SQL error the handler returns the full raw query string and the database error message to the client, revealing schema details and aiding further injection attacks."
  },
  {
    "vulnerability": "Sensitive Data Exposure",
    "function": "do_login",
    "severity": "HIGH",
    "reason": "On a successful (or injected) query the handler returns the entire row including the 'secret' column, leaking privileged data such as session tokens or canary flags to the caller."
  },
  {
    "vulnerability": "Missing CSRF Protection",
    "function": "do_POST",
    "severity": "MEDIUM",
    "reason": "The /login and /ping POST endpoints accept requests without any anti-CSRF token or SameSite cookie enforcement, allowing a malicious page to trigger state-changing actions on behalf of an authenticated user."
  },
  {
    "vulnerability": "No Rate Limiting / Brute-Force Protection",
    "function": "do_POST",
    "severity": "MEDIUM",
    "reason": "The /login endpoint imposes no throttling, lockout, or CAPTCHA, permitting unlimited credential-guessing or SQL-injection attempts from a single source."
  },
  {
    "vulnerability": "Unrestricted Network Binding",
    "function": "main",
    "severity": "LOW",
    "reason": "The server binds to 0.0.0.0, exposing the vulnerable endpoints on every network interface rather than restricting access to localhost or a trusted subnet."
  }
]
